# ---------------- Script parser -----------------
FUNC_NAME_RE = re.compile(r'^(?:function\s+)?([^\s()]+?)\s*\(\s*\)')
FUNC_NAME2_RE = re.compile(r'^function\s+([^\s()]+)')
ALLOWED_FN_PUNCT = set("!#%*+,-./:=?@^_~")

def is_valid_fn_name(name):
    if not name: return False
    for c in name:
        if c.isalnum() or c in ALLOWED_FN_PUNCT:
            continue
        return False
    return True

def parse_function_line(line):
    # line must start at col 0 (not #)
    if not line or line[0] in ' \t#':
        return None
    m=FUNC_NAME_RE.match(line)
    if m:
        name=m.group(1)
        return name if is_valid_fn_name(name) else None
    m=FUNC_NAME2_RE.match(line)
    if m:
        name=m.group(1)
        # for function foo { -- require next char space/{/(/end? name capture stops before space/paren
        return name if is_valid_fn_name(name) else None
    return None

def strip_describe(s):
    return (s or "").strip()

def parse_symbol(value, line):
    # value string or None; returns dict or raises
    if not value:
        raise ScriptError(f"@meta(line {line}) invalid symbol value")
    # pattern: (+|@)name optionally [`fn`]
    m=re.fullmatch(r'([+@])([A-Za-z0-9_\-\.:@]+)(?:\[`([^\s`]+)`\])?', value)
    if not m:
        raise ScriptError(f"@meta(line {line}) invalid symbol value")
    prefix, name, fn = m.group(1), m.group(2), m.group(3)
    if fn is not None and not all(c in FN_NAME_CHARS for c in fn):
        raise ScriptError(f"@meta(line {line}) invalid symbol value")
    choice = ('Fn', fn, True) if fn else None
    return {"prefix":prefix,"name":name,"choice":choice}

