ALLOWED_FN_PUNCT = set("!#%*+,-./:=?@^_~")

def is_valid_fn_name(name):
    if not name: return False
    for c in name:
        if c.isalnum() or c in ALLOWED_FN_PUNCT:
            continue
        return False
    return True

def parse_function_line(line):
    # line must start at col 0 (not #)
    if not line or line[0] in ' \t#':
        return None
    m=FUNC_NAME_RE.match(line)
    if m:
        name=m.group(1)
        return name if is_valid_fn_name(name) else None
    m=FUNC_NAME2_RE.match(line)
    if m:
        name=m.group(1)
        # for function foo { -- require next char space/{/(/end? name capture stops before space/paren
        return name if is_valid_fn_name(name) else None
    return None

def strip_describe(s):
    return (s or "").strip()

def parse_symbol(value, line):
    # value string or None; returns dict or raises
    if not value:
        raise ScriptError(f"@meta(line {line}) invalid symbol value")
    # pattern: (+|@)name optionally [`fn`]
    m=re.fullmatch(r'([+@])([A-Za-z0-9_\-\.:@]+)(?:\[`([^\s`]+)`\])?', value)
    if not m:
        raise ScriptError(f"@meta(line {line}) invalid symbol value")
    prefix, name, fn = m.group(1), m.group(2), m.group(3)
    if fn is not None and not all(c in FN_NAME_CHARS for c in fn):
        raise ScriptError(f"@meta(line {line}) invalid symbol value")
    choice = ('Fn', fn, True) if fn else None
    return {"prefix":prefix,"name":name,"choice":choice}

class ParseResult:
    def __init__(self, root, source, functions):
        self.root=root; self.source=source; self.functions=functions

def parse_script(source, path):
    root_name=script_stem(path)
    root=Command(name=root_name, is_root=True)
    functions=set()
    lines=source.splitlines()
    pending=None  # Command placeholder for @cmd block
    seen_function=False
    last_desc_target=None  # ('cmd', command) or ('fo',fo) etc object with .describe
    prev_was_comment=False
    # duplicate maps per target command id -> dict
    dup_maps={}  # id(command) -> (fo_map,pos_map,env_map)
    def get_dup(cmd):
        k=id(cmd)
        if k not in dup_maps: dup_maps[k]=({},{},{})
        return dup_maps[k]
    # collect fn refs: (line, fnname)
    fn_refs=[]
    def collect_refs_from_param(obj, line):
        d=getattr(obj,'default',None)
        if d and d[0]=='Fn': fn_refs.append((line,d[1]))
        c=getattr(obj,'choice',None)
        if c and c[0]=='Fn': fn_refs.append((line,c[1]))

    def insert_command(cmd, fn_name, fn_line):
        segments=fn_name.split('::')
        # navigate parents
        parent=root
        for seg in segments[:-1]:
            pname=seg.rstrip('_')
            found=None
            for s in parent.subcommands:
                if s.name==pname:
                    found=s; break
            if found is None:
                raise ScriptError(f"{fn_name}(line {fn_line}) lack of parent command")
            parent=found
        last=segments[-1].rstrip('_')
        cmd.name=last
        cmd.command_fn=fn_name
        cmd.internal_fn=fn_name
        cmd.fn_line=fn_line
        cmd.parent=parent
        # generated alias
        gen=None
        if '_' in last:
            cand=last.replace('_','-')
            if cand!=last and not cand.startswith('-'):
                gen=cand
        aliases=[]
        if gen: aliases.append(gen)
        # explicit aliases (already stored in cmd.explicit_aliases as list, cmd.aliases currently explicit)
        explicit=list(cmd.explicit_aliases or [])
        aliases.extend(explicit)
        cmd.aliases=aliases
        parent.subcommands.append(cmd)
        # if this is a main subcommand, set parent command_fn
        if last=='main':
            parent.command_fn=fn_name
        # if parent now has subcommands and parent is not root, its command_fn becomes None unless it is via ::main child?
        # Root handling: root command_fn stays if main function itself; for non-root parent that had its own fn, when first child added, clear it
        # But if child just added is 'main', we set parent.command_fn above to child's fn.
        # Determine: if parent is not root and last!='main' and parent.internal_fn is not None and parent.command_fn==parent.internal_fn:
        # However parent.command_fn could have been set by a previous ::main child; then keep.
        if parent is not root and last!='main':
            # if parent's command_fn equals its own internal_fn, clear
            if parent.command_fn is not None and parent.command_fn==parent.internal_fn:
                parent.command_fn=None
        return cmd

    for idx, raw_line in enumerate(lines):
        line_no=idx+1
        line=raw_line.rstrip('\r')
        # Function line?
        fn_name=parse_function_line(line)
        if fn_name is not None:
            functions.add(fn_name)
            seen_function=True
            prev_was_comment=False
            last_desc_target=None
            if pending is not None:
                insert_command(pending, fn_name, line_no)
                pending=None
            else:
                if fn_name=='main':
                    root.command_fn='main'
                elif fn_name=='_argc_before':
                    root.before_hook='_argc_before'
                elif fn_name=='_argc_after':
                    root.after_hook='_argc_after'
                # Note: hooks can also appear when pending? If pending was a cmd for _argc_before weird, above handled as subcommand.
                # Also hooks defined after a cmd block? pending handled.
            # hooks also recognized even if they were a pending cmd? skip
            if fn_name=='_argc_before' and root.before_hook is None:
                # In case it was consumed as pending subcommand, original still sets? Unlikely; keep only if not pending-consumed above
                # We already consumed pending, cannot know. To match typical scripts hooks are not @cmd, fine.
                pass
            continue
        # Comment line?
        if line.startswith('#'):
            # strip leading #'s
            stripped_hash=line.lstrip('#')
            trimmed=stripped_hash.lstrip(' \t')
            if trimmed.startswith('@') and len(trimmed)>1 and not trimmed[1] in ' \t':
                # tag token until whitespace
                m=re.match(r'@([^\s]+)(.*)$', trimmed, flags=re.S)
                tag_token=m.group(1); rest=m.group(2)
                # special prefixes for param tags: if trimmed starts with @arg etc and next char not ws/eol, syntax error
                for pfx in ('arg','option','flag','env'):
                    if trimmed.startswith('@'+pfx) and len(trimmed)>len(pfx)+1 and trimmed[len(pfx)+1] not in ' \t':
                        raise ScriptError(f"syntax error at line {line_no}")
                # known tags
                known=('describe','cmd','alias','arg','option','flag','env','meta','version')
                if tag_token not in known:
                    raise ScriptError(f"@{tag_token}(line {line_no}) is unknown tag")
                tag=tag_token
                # empty alias/meta peculiarities handled later but need raw rest presence
                # Determine target
                if tag=='cmd':
                    if pending is not None:
                        raise ScriptError(f"@cmd(line {pending.cmd_line}) missing function?")
                    pending=Command(name="", is_root=False)
                    pending.cmd_line=line_no
                    pending.describe=rest.strip() if rest else ""
                    # describe continuation may append; keep raw for now striped later? We'll set describe = rest.lstrip... final strip later
                    pending.describe=rest.strip()
                    last_desc_target=pending
                    prev_was_comment=True
                    continue
                # non-cmd tag target selection
                if pending is not None:
                    target=pending
                elif not seen_function:
                    target=root
                else:
                    raise ScriptError(f"@{tag}(line {line_no}) shouldn't be here, @cmd is missing?")
                # handle tag
                if tag=='describe':
                    target.describe=rest.strip()
                    last_desc_target=target
                elif tag=='version':
                    target.version=rest.strip()
                    last_desc_target=None
                elif tag=='alias':
                    if not rest.strip():
                        raise ScriptError(f"@alias(line {line_no}) is unknown tag")
                    first=rest.strip().split()[0]
                    # alias values: split by ','; also '|' seems to truncate? Observed a|b -> ['a']; this is because value parsing maybe first token up to? Let's implement split on ',' and for each take up to '|'?
                    # Actually a|b gave ['a'] - suggests they split by regex [,\|]? But then would include b. Maybe alias name valid chars stop at |, and rest ignored.
                    # We'll parse: take first token, split ',', for each part cut at '|' and keep first piece if part contains '|'? For a|b -> a. For a,b|c -> a,b?
                    vals=[]
                    for part in first.split(','):
                        if '|' in part:
                            part=part.split('|')[0]
                        if part!='' or True:
                            vals.append(part)
                    # If first contains | without comma, only first piece (as above one)
                    target.explicit_aliases=vals
                    target.alias_line=line_no
                    if target is root or pending is not None:
                        # For root, aliases are directly explicit (no generated). For pending, aliases finalized at insert.
                        if target is root:
                            target.aliases=vals
                        else:
                            # store temporarily in aliases too (will be recomputed at insert from explicit)
                            target.aliases=vals
                    last_desc_target=None
                elif tag=='meta':
                    if rest=="":
                        raise ScriptError(f"@meta(line {line_no}) is unknown tag")
                    if not rest.strip():
                        raise ScriptError(f"syntax error at line {line_no}")
                    # parse key value: key is first token, must not contain '=' (syntax error if key=value form and no space)
                    body=rest.strip()
                    # If body matches key=value with no spaces in key part -> syntax error observed for "# @meta key=value"
                    # Detect: first token contains '='
                    first_tok=body.split()[0]
                    if '=' in first_tok:
                        raise ScriptError(f"syntax error at line {line_no}")
                    parts=body.split(None,1)
                    key=parts[0]; val=parts[1].strip() if len(parts)>1 else None
                    # validations
                    if key=='version':
                        if not val:
                            raise ScriptError(f"@meta(line {line_no}) invalid version value")
                        target.version=val
                    if key=='symbol':
                        sym=parse_symbol(val, line_no)
                        target.symbol=sym
                    target.metadata[key]=val
                    last_desc_target=None
                elif tag in ('arg','env'):
                    obj=parse_arg_tag(rest, line_no, tag)
                    collect_refs_from_param(obj, line_no)
                    fo_map,pos_map,env_map=get_dup(target)
                    if tag=='arg':
                        if obj.id in pos_map:
                            raise ScriptError(f"@arg(line {line_no}) has '{obj.id}' already exists at line {pos_map[obj.id]}")
                        pos_map[obj.id]=line_no
                        target.positionals.append(obj)
                    else:
                        if obj.id in env_map:
                            raise ScriptError(f"@env(line {line_no}) has '{obj.id}' already exists at line {env_map[obj.id]}")
                        env_map[obj.id]=line_no
                        target.envs.append(obj)
                    last_desc_target=obj
                elif tag in ('option','flag'):
                    obj=parse_fo_tag(rest, line_no, tag)
                    collect_refs_from_param(obj, line_no)
                    fo_map,pos_map,env_map=get_dup(target)
                    for nm in obj.names:
                        if nm in fo_map:
                            raise ScriptError(f"@{tag}(line {line_no}) has '{nm}' already exists at line {fo_map[nm]}")
                        fo_map[nm]=line_no
                    target.flag_options.append(obj)
                    last_desc_target=obj
                prev_was_comment=True
                continue
            else:
                # regular comment: continuation if last_desc_target and prev_was_comment
                if last_desc_target is not None and prev_was_comment:
                    cont=stripped_hash
                    if cont[:1] in (' ','\t'):
                        cont=cont[1:]
                    # append
                    cur=getattr(last_desc_target,'describe','') or ""
                    if cur=="":
                        last_desc_target.describe=cont
                    else:
                        last_desc_target.describe=cur+"\n"+cont
                prev_was_comment=True
                continue
        else:
            # non-comment line (blank or code)
            prev_was_comment=False
            last_desc_target=None
            continue
    # end for
    if pending is not None:
        # phantom subcommand named root
        pending.name=root.name
        pending.command_fn=None
        pending.internal_fn=None
        pending.parent=root
        # aliases: explicit only? generated based on root name? root name may contain _
        # For nofn test root name 'nofn' no alias. Keep explicit as aliases if any, plus generated?
        explicit=list(pending.explicit_aliases or [])
        gen=None
        if '_' in pending.name:
            cand=pending.name.replace('_','-')
            if cand!=pending.name and not cand.startswith('-'): gen=cand
        pend_alias=[]
        if gen: pend_alias.append(gen)
        pend_alias.extend(explicit)
        pending.aliases=pend_alias
        root.subcommands.append(pending)
        pending=None
    # hooks: if functions contain hooks but they were defined as pending? Typical definitions without @cmd already set. Also if hooks defined before any tags, set.
    if '_argc_before' in functions and root.before_hook is None:
        # Only set if _argc_before was not a subcommand function? Check if any subcommand internal_fn == it
        is_cmd=False
        def check_cmd(c):
            nonlocal is_cmd
            if c.internal_fn=='_argc_before': is_cmd=True
            for s in c.subcommands: check_cmd(s)
        check_cmd(root)
        if not is_cmd:
            root.before_hook='_argc_before'
    if '_argc_after' in functions and root.after_hook is None:
        is_cmd=False
        def check_cmd2(c):
            nonlocal is_cmd
            if c.internal_fn=='_argc_after': is_cmd=True
            for s in c.subcommands: check_cmd2(s)
        check_cmd2(root)
        if not is_cmd:
            root.after_hook='_argc_after'
    # finalize describes
    def fin_cmd(c):
        c.describe=strip_describe(c.describe)
        for f in c.flag_options: f.describe=strip_describe(f.describe)
        for p in c.positionals: p.describe=strip_describe(p.describe)
        for e in c.envs: e.describe=strip_describe(e.describe)
        # metadata derived fields
        md=c.metadata
        if 'require-tools' in md and md['require-tools'] is not None:
            c.require_tools=md['require-tools'].split(',')
        else:
            c.require_tools=None
        if 'dotenv' in md:
            c.dotenv= md['dotenv'] if md['dotenv'] is not None else ".env"
        else:
            c.dotenv=None
        if c is root and 'combine-shorts' in md:
            c.combine_shorts=True
        if 'symbol' in md and c.symbol is None:
            # already parsed when meta encountered; but if symbol set, keep
            try:
                c.symbol=parse_symbol(md['symbol'], c.cmd_line or 1)
            except ScriptError:
                pass
        for s in c.subcommands: fin_cmd(s)
    fin_cmd(root)
    # validate fn refs sorted by line
    for ln, fn in sorted(fn_refs, key=lambda x:x[0]):
        if fn not in functions:
            raise ScriptError(f"{fn}(line {ln}) is missing")
    # alias/command conflicts
    def check_conflicts(cmd):
        seen={}  # value -> line
        for child in cmd.subcommands:
            entries=[]
            entries.append((child.name, child.fn_line, 'cmd', child.internal_fn or child.name))
            for al in (child.explicit_aliases or []):
                entries.append((al, child.alias_line, 'alias', None))
            for val, ln, kind, fnname in entries:
                if val in seen:
                    prev=seen[val]
                    if kind=='alias':
                        raise ScriptError(f"@alias(line {ln}) conflicts with cmd or alias at line {prev}")
                    else:
                        raise ScriptError(f"{fnname}(line {ln}) conflicts with cmd or alias at line {prev}")
                seen[val]=ln
        for child in cmd.subcommands:
            check_conflicts(child)
    check_conflicts(root)
    # env inheritance
    def inherit_envs(cmd, parent_envs):
        # parent_envs: list of EnvP from parent (already merged)
        own=cmd.envs
        if cmd is not root:
            own_ids=set(e.id for e in own)
            merged=[]
            for pe in parent_envs:
                if pe.id not in own_ids:
                    ne=pe.copy(); ne.inherited=True; merged.append(ne)
            merged.extend(own)
            cmd.envs=merged
        for s in cmd.subcommands:
            inherit_envs(s, cmd.envs)
    inherit_envs(root, [])
    # flag-options inheritance if root metadata has inherit-flag-options
    if 'inherit-flag-options' in root.metadata:
        def inherit_fos(cmd):
            for child in cmd.subcommands:
                own_ids=set(f.id for f in child.flag_options)
                merged=[]
                for pf in cmd.flag_options:
                    # skip auto help/version if present (not yet inserted at this stage, so none)
                    if pf.id not in own_ids:
                        nf=pf.copy(); nf.inherited=True; merged.append(nf)
                child.flag_options=merged+child.flag_options
                inherit_fos(child)
        inherit_fos(root)
    # auto help/version
    def add_auto(cmd):
        # determine if any FO long doesn't start with --
        nonstd=False
        for f in cmd.flag_options:
            if f.long_name and not f.long_name.startswith('--'):
                nonstd=True; break
        help_long='-help' if nonstd else '--help'
        ver_long='-version' if nonstd else '--version'
        # check existing names
        all_names=set()
        for f in cmd.flag_options:
            if f.long_name: all_names.add(f.long_name)
            if f.short_name: all_names.add(f.short_name)
        has_help = ('--help' in all_names) or ('-help' in all_names)
        has_version = ('--version' in all_names) or ('-version' in all_names)
        # describe trigger: any FO with inherited==False and describe non-empty (before adding auto)
        trig=any((not f.inherited) and (f.describe) for f in cmd.flag_options)
        if not has_help:
            short='-h' if '-h' not in all_names else None
            hf=FO(id='help', long_name=help_long, short_name=short, describe=('Print help' if trig else ''), flag=True, notations=[], required=False, multiple_values=False, multiple_occurs=False, num_args=[0,0], delimiter=None, terminated=False, prefixed=False, assigned=False, default=None, choice=None, env=None, inherited=False, is_auto=True, names=[x for x in [short,help_long] if x])
            cmd.flag_options.append(hf); all_names.add(help_long)
            if short: all_names.add(short)
        need_version = cmd.is_root or (cmd.version is not None)
        if need_version and not has_version:
            short='-V' if '-V' not in all_names else None
            vf=FO(id='version', long_name=ver_long, short_name=short, describe=('Print version' if trig else ''), flag=True, notations=[], required=False, multiple_values=False, multiple_occurs=False, num_args=[0,0], delimiter=None, terminated=False, prefixed=False, assigned=False, default=None, choice=None, env=None, inherited=False, is_auto=True, names=[x for x in [short,ver_long] if x])
            cmd.flag_options.append(vf)
        for s in cmd.subcommands: add_auto(s)
    add_auto(root)
    return ParseResult(root, source, functions)

