def format_section(entries, allow_long=True):
    # entries: list of dict {left, right_lines(list), multi(bool)}
    if not entries: return []
    long_mode=allow_long and any(e.get('multi') for e in entries)
    out=[]
    if long_mode:
        for idx,e in enumerate(entries):
            out.append("  "+e['left'])
            right_lines=e.get('right_lines') or []
            if right_lines:
