                    out.append(" "*10+seg)
            if idx < len(entries)-1:
                out.append('')
        return out
    maxlen=max(disp_width(e['left']) for e in entries)
    right_col=2+maxlen+2
    for e in entries:
        right_lines=e.get('right_lines') or []
        if not right_lines or (len(right_lines)==1 and right_lines[0]==""):
            out.append("  "+e['left'])
        else:
            text='\n'.join(right_lines)
            wrapped=wrap_text_lines(text,right_col)
            pad=" "*(right_col-2-disp_width(e['left']))
            out.append("  "+e['left']+pad+wrapped[0])
            for seg in wrapped[1:]:
                out.append(" "*right_col+seg)
