            entries.append({'left':positional_usage(p),'right_lines':rl,'multi':multi})
        lines.extend(format_section(entries,allow_long=True))
    user=[f for f in cmd.flag_options if not f.is_auto]
    if user:
        lines.append(''); lines.append('OPTIONS:')
        entries=[]
        for f in cmd.flag_options:
            rl,multi=entry_right(f.describe,f.default,f.choice,f.env)
            entries.append({'left':fo_left(f),'right_lines':rl,'multi':multi})
