            entries.append({'left':left,'right_lines':rl,'multi':multi})
        lines.extend(format_section(entries,allow_long=True))
    return "\n".join(lines)+"\n\n"

def render_version(cmd):
    name="-".join(cmd.path_names())
    ver=cmd.version if cmd.version is not None else "0.0.0"
    return f"{name} {ver}\n"

