    elif sys.platform=='darwin': env['ARGC_OS']='macos'
    elif sys.platform.startswith('win'): env['ARGC_OS']='windows'
    else: env['ARGC_OS']=sys.platform
    exedir=current_exe_dir()
    if exedir:
        old=env.get('PATH','')
        env['PATH']=exedir+(os.pathsep+old if old else '')
