    try:
        p=subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env)
    except Exception:
        return []
    try:
        text=p.stdout.decode('utf-8','surrogateescape')
    except Exception:
