def compute_signs(cmd):
    user=[f for f in cmd.flag_options if not f.is_auto]
    if not user: return set()
    signs=set('-')
    for f in user:
        for nm in (f.long_name,f.short_name):
            if nm and nm[0] in '-+': signs.add(nm[0])
    return signs

