    if any(c in base for c in (' ','\t')): return False
    if token[0]=='-':
        return len(token)>1 and not token.startswith('---')
    if token[0]=='+':
        return len(token)>1 and token[1]!='+'
    return False

def fo_uses_name(cmd, name, exclude_id=None):
    for f in cmd.flag_options:
        if exclude_id is not None and f.id==exclude_id: continue
        if f.long_name==name or f.short_name==name: return True
    return False

def is_help_token(cmd, token):
    base=token.split('=',1)[0]
    if base in ('--help','-help'): return True
    if base=='-h':
        # if a non-help FO uses -h, not help
        for f in cmd.flag_options:
            if (f.long_name=='-h' or f.short_name=='-h') and f.id!='help':
                return False
        return True
    return False

def is_version_token(cmd, token, is_root_level):
    base=token.split('=',1)[0]
    if base in ('--version','-version'):
        if is_root_level: return True
        for f in cmd.flag_options:
            if f.long_name in ('--version','-version'): return True
        return False
    if base=='-V':
        # non-version use takes precedence
        for f in cmd.flag_options:
            if (f.long_name=='-V' or f.short_name=='-V') and f.id!='version':
                return False
        if is_root_level: return True
        for f in cmd.flag_options:
            if f.id=='version' and (f.short_name=='-V' or f.long_name=='-V'): return True
        return False
    return False

