        for fo in cmd.flag_options:
            eff=fo_eff.get((li,id(fo)))
            if not eff or eff.get('kind')=='env_invalid': continue
            var=var_name(fo.id)
            if eff['kind']=='count':
                stmts.append(f"argc_{var}={eff['count']}")
            elif eff['kind']=='prefixed':
