                    grouped[k].extend(vs)
                for k in order:
                    joined="|".join(_value_render(v) for v in grouped[k])
                    stmts.append(f'argc_{var}["{k}"]={joined}')
            elif eff['kind']=='values':
                vals=eff['values']
                if fo.multiple_values:
                    stmts.append(_array_assign(f"argc_{var}", vals))
                else:
                    v=vals[0] if vals else ""
                    stmts.append(f"argc_{var}={_value_render(v)}")
    final=self.cur
    for pi,p in enumerate(final.command.positionals):
        vals=pos_eff[pi]['values'] if pi<len(pos_eff) else []
        if not vals: continue
        var=var_name(p.id)
        if p.multiple:
            stmts.append(_array_assign(f"argc_{var}", vals))
        else:
            stmts.append(f"argc_{var}={_value_render(vals[0])}")
    stmts.append(_array_assign("argc__args", self.full_argv))
    if internal:
        stmts.append(f"argc__cmd_arg_index={final.token_index}")
        if len(self.levels)>1:
