                seen.add(t); out.append(t)
    return out

def build_success_eval(root, script_path, parser, stmts, eff_positionals, internal=False, internal_call_fn=None):
    prefix=argcfile_prefix(script_path)
    # ARGC_VARS content
    b64_stmts=list(stmts)
    final_cmd=parser.cur.command
    if root.before_hook:
        b64_stmts.append(root.before_hook)
    if root.after_hook:
        if internal or final_cmd.command_fn:
            b64_stmts.append(root.after_hook)
    b64_content="".join(s+";" for s in b64_stmts)
    lines=[]
    if prefix:
        lines.append(prefix.rstrip('\n'))
    lines.append(f"export ARGC_VARS={b64_encode_text(b64_content)}")
    # dotenv + env exports
    if root.dotenv is not None:
        lines.append(DOTENV_FUNC)
        lines.append(f"_argc_load_dotenv {shell_escape(root.dotenv)}")
    # env defaults for final command envs
    eff=parser.eff_env
    for e in final_cmd.envs:
        if e.id not in eff and e.default:
            if e.default[0]=='Value':
                lines.append(f"export {e.id}={shell_escape(e.default[1])}")
            else:
                lines.append(f"export {e.id}=`{e.default[1]}`")
    # assignments (stmts)
    lines.extend(stmts)
    if not internal:
        tools=aggregate_require_tools(parser)
        if tools:
            lines.append('')
            lines.append(REQUIRE_FUNC)
            lines.append("_argc_require_tools "+" ".join(shell_escape(t) for t in tools))
            lines.append('')
        if root.before_hook:
            lines.append(root.before_hook)
        if final_cmd.command_fn:
            call=final_cmd.command_fn
            if eff_positionals:
                lines.append(call+" "+" ".join(_value_render(v) for v in eff_positionals))
            else:
                lines.append(call)
            if root.after_hook:
                lines.append(root.after_hook)
    else:
        if root.before_hook:
            lines.append(root.before_hook)
        call=internal_call_fn
        if eff_positionals:
            lines.append(call+" "+" ".join(_value_render(v) for v in eff_positionals))
        else:
            lines.append(call)
        if root.after_hook:
            lines.append(root.after_hook)
        lines.append('exit')
    return "\n".join(lines)+"\n"

def do_eval(script_path, args):
    """returns stdout text for --argc-eval (always). args are user args after file."""
    # load
    try:
        source=load_script(script_path)
    except LoadError as e:
        return eval_parse_error(e.message)
    # parallel marker: no parse
    if args and args[0]=='___parallel___':
        if len(args)<2:
            return eval_parse_error("No parallel command")
        decoded=""
        raw=os.environ.get('ARGC_VARS')
        if raw:
            try:
                decoded=base64.b64decode(raw, validate=True).decode('utf-8')
            except Exception:
                decoded=""
        fn=args[1]; rest=args[2:]
        line=decoded+fn
        if rest:
            line+=" "+" ".join(shell_escape(a) for a in rest)
        return line+"\n"
    # parse script
    try:
        res=parse_script(source, script_path)
    except ScriptError as e:
        return eval_parse_error(str(e))
    root=res.root
    # internal marker
    if len(args)>=2 and args[0]=='___internal___':
        call_fn=args[1]; full=args[2:] if len(args)>2 else []
        if not full:
            full=['prog']; user=[]
        else:
            user=full[1:]
        parser=ArgParser(root, script_path, user, full[0], lax=True, internal_full_argv=full)
        try:
            parser.parse()
        except ArgError as e:
            # lax should rarely raise; treat as empty? Original internal never errors? Return error eval?
            return render_error_eval(script_path, str(e))
        fo_eff,pos_eff,eff_pos,excess=parser._compute_effectives()
        stmts=parser._build_statements(fo_eff,pos_eff,eff_pos,internal=True,call_fn=call_fn)
        return build_success_eval(root, script_path, parser, stmts, eff_pos, internal=True, internal_call_fn=call_fn)
    # normal
    prog=script_stem(script_path)
    parser=ArgParser(root, script_path, args, prog, lax=False)
    try:
        act=parser.parse()
        if isinstance(act, ActionResult):
            if act.kind=='help':
                return render_message_eval(script_path, render_help(act.command), 0)
            else:
                return render_message_eval(script_path, render_version(act.command), 0)
        # default subcommand at end
        cur=parser.cur
        if cur.command.subcommands and not cur.raw_positionals:
            dc=find_default_child(cur.command)
            if dc is not None:
                parser.descend(dc, cur.token_index)
                cur=parser.cur
        # group disposition
        if cur.command.subcommands and cur.command.command_fn is None:
            fo_eff,pos_eff,eff_pos,excess=parser._compute_effectives()
            parser._validate_fo_choices(fo_eff); parser._validate_duplicates(); parser._validate_required_fos(fo_eff)
            if cur.had_cli_fo:
                poss=", ".join(cur.command.all_sub_names())
                disp="-".join(cur.command.path_names())
                raise ArgError(f"error: `{disp}` requires a subcommand but one was not provided\n  [subcommands: {poss}]")
            return render_message_eval(script_path, render_help(cur.command),0)
        fo_eff,pos_eff,eff_pos,excess=parser._compute_effectives()
        parser._validate_full(fo_eff,pos_eff,excess)
        stmts=parser._build_statements(fo_eff,pos_eff,eff_pos,internal=False)
        return build_success_eval(root, script_path, parser, stmts, eff_pos, internal=False)
    except ArgError as e:
        return render_error_eval(script_path, str(e))

