# ---------------- Parallel -----------------
import threading
def do_parallel(script_path, args):
    bash=find_bash()
    if not bash:
        eprint("Shell not found"); return 1
    try:
        source=load_script(script_path)
    except Exception as e:
        print_load_error(e); return 1
    if "--argc-eval" not in source:
        eprint("Parallel only available for argc based scripts."); return 1
    groups=[]; cur=[]
    for a in args:
        if a==':::':
            groups.append(cur); cur=[]
        else:
            cur.append(a)
    groups.append(cur)
    groups=[g for g in groups if g]
    if not groups:
        return 0
    procs=[]; results=[None]*len(groups)
    threads=[]
    env=dict(os.environ)
    for idx,g in enumerate(groups):
        try:
            p=subprocess.Popen([bash, script_path, '___parallel___']+g, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.DEVNULL, env=env)
        except OSError as e:
            # treat as failure with no output? Reference likely returns 1
            results[idx]=(1,b'',b''); continue
        procs.append(p)
        def worker(i,p):
            out,err=p.communicate(); results[i]=(p.returncode,out,err)
        th=threading.Thread(target=worker,args=(idx,p)); th.start(); threads.append(th)
    for th in threads: th.join()
    # If a spawn failed slot remained, fill
    rc=0
    for item in results:
        if item is None: rc=1; continue
        code,out,err=item
        if code!=0: rc=1
        if out: sys.stdout.buffer.write(out); sys.stdout.buffer.flush()
        if err: sys.stderr.buffer.write(err); sys.stderr.buffer.flush()
    return rc
PY
