{"command":"cat >> src/argc.py <<'PY'
# ---------------- Compgen -----------------

def truncate_desc(s):
    s=str(s or "").split('\n')[0]
    if len(s)>80:
        return s[:83]+"..."
    return s

class Cand:
    __slots__=('value','display','desc','kind','append','is_file')
    def __init__(self,value,display=None,desc="",kind="39",append=True,is_file=False):
        self.value=str(value); self.display=str(display if display is not None else value); self.desc=truncate_desc(desc); self.kind=str(kind); self.append=bool(append); self.is_file=is_file

def file_hint(notation):
    n=str(notation or "").upper()
    if any(x in n for x in ("FILE","PATH","ARG","ANY")):
        return 'file'
    if "DIR" in n or "FOLDER" in n:
        return 'dir'
    return None

def file_candidates(prefix, dir_only=False):
    if '/' in prefix:
        idx=prefix.rfind('/'); dirpart=prefix[:idx+1]; base=prefix[idx+1:]; listdir=dirpart if dirpart else '/'
    else:
        dirpart=''; base=prefix; listdir='.'
    try:
        entries=list(os.scandir(listdir))
    except Exception:
        return []
    out=[]
    import stat as _stat
    for e in entries:
        name=e.name
        if not name.startswith(base): continue
        if not base.startswith('.') and name.startswith('.'): continue
        try:
            st=e.stat(follow_symlinks=True)
        except Exception:
            continue
        is_dir=_stat.S_ISDIR(st.st_mode)
        if dir_only and not is_dir: continue
        is_link=e.is_symlink()
        if is_dir:
            kind='1;34'; append=False; suffix='/'
        elif is_link:
            kind='1;36'; append=True; suffix=''
        elif (st.st_mode & 0o111):
            kind='1;32'; append=True; suffix=''
        else:
            kind='39'; append=True; suffix=''
        disp=name+suffix; val=dirpart+name+suffix
        out.append((name.lower().replace(' ',''), Cand(val,disp,"",kind,append,True)))
    out.sort(key=lambda x:x[0])
    return [c for _,c in out]

def parse_choice_fn_lines(lines):
    cands=[]
    for ln in lines:
        if '\t' in ln:
            v,d=ln.split('\t',1)
            cands.append((v.strip(), d.strip()))
        else:
            cands.append((ln.strip(), ""))
    return cands

def candidates_for_param(parser, param, prefix, value_index=0, is_option=False):
    # delimiter segment handling
    delim=getattr(param,'delimiter',None)
    base_prefix=""; exclude=set(); search=prefix
    if delim and delim in prefix:
        parts=prefix.split(delim); exclude=set(parts[:-1]); search=parts[-1]; base_prefix=delim.join(parts[:-1])+delim
    choice=getattr(param,'choice',None)
    if choice:
        raw=[]
        if choice[0]=='Values':
            raw=[(str(v),"") for v in choice[1]]
        else:
            fn=choice[1]
            if not hasattr(parser,'_choice_raw_cache'): parser._choice_raw_cache={}
            if fn not in parser._choice_raw_cache:
                parser._choice_raw_cache[fn]=run_choice_fn_raw(fn, parser.script_path, parser.choice_argv)
            raw=parse_choice_fn_lines(parser._choice_raw_cache[fn])
        out=[]
        for v,d in raw:
            if v in exclude: continue
            if not v.startswith(search): continue
            out.append(Cand(base_prefix+v, base_prefix+v, d, "39", True))
        return out
    # file hint
    if is_option:
        notations=getattr(param,'notations',[]) or []
        notation=notations[min(value_index, len(notations)-1)] if notations else ""
    else:
        notation=getattr(param,'notation',"")
    hint=file_hint(notation)
    if hint=='file':
        cands=file_candidates(search, False)
    elif hint=='dir':
        cands=file_candidates(search, True)
    else:
        return []
    if base_prefix:
        out=[]
        for c in cands:
            if c.value in exclude: continue
            out.append(Cand(base_prefix+c.value, base_prefix+c.display, c.desc, c.kind, c.append, True))
        return out
    return cands

def subcommand_candidates(cmd):
    out=[]
    for s in cmd.subcommands:
        desc=s.describe or ""
        out.append(Cand(s.name,s.name,desc,"35",True))
        for al in (s.aliases or []):
            if len(al)>1:
                out.append(Cand(al,al,desc,"35",True))
    # append help pseudo if there's at least one subcommand and no real help subcommand
    if cmd.subcommands and not any(s.name=='help' for s in cmd.subcommands):
        desc="Show help for a command" if any((s.describe or "") for s in cmd.subcommands) else ""
        out.append(Cand('help','help',desc,"35",True))
    return out

def resolve_compgen_script(file_arg, words):
    if file_arg:
        return file_arg
    if not words: return None
    cmd=words[0]
    if cmd=='argc':
        return find_argcfile()
    if '/' in cmd:
        return cmd if os.path.exists(cmd) else None
    found=shutil.which(cmd)
    return found

def unescape_prev_token(tok):
    if len(tok)>=2 and tok[0]==tok[-1] and tok[0] in ("'",'"'):
        return tok[1:-1]
    # backslash escapes: \<char> -> <char>
    return re.sub(r'\\(.)', r'\1', tok)

# formatting helpers
BASH_ESC=set(' !"$\&\'();<>\\`|')
def bash_escape_cand(v):
    return ''.join(('\\'+c) if c in BASH_ESC else c for c in str(v))
TCSH_ESC=set(' !"$\&\'()*;<>?\\`{|')
def tcsh_escape_cand(v):
    return ''.join(('\\'+c) if c in TCSH_ESC else c for c in str(v))
ZSH_ESC=set(' !"$\&\'()*;<>?[`|')
def zsh_escape_cand(v):
    out=""
    for c in str(v):
        if c=='\\': out+='\\\\\\'
        elif c in ZSH_ESC: out+='\\\\'+c
        elif c==':': out+='\\:'
        else: out+=c
    return out
PS_QUOTE=set(' " $\&\'(),;`{|}')
NU_QUOTE=set(' "\'();[`{|}')
XON_QUOTE=set(' !"#&\'()*;<>[]`{|}')
def quote_if(v, chars):
    v=str(v)
    return f"'{v}'" if any(c in chars for c in v) else v
ELVISH_COLORS={'35':'magenta','36':'cyan','1;36':'cyan bold','39':'default','1;34':'blue bold','1;32':'green bold'}

def format_compgen(shell, cands, prefix_filtered, quote_char):
    # prefix_filtered is effective current (without quote) used for bash common prefix comparison
    if not cands:
        return ""
    # quote handling: append becomes False if quote_char
    if quote_char:
        for c in cands: c.append=False
    if shell=='fish':
        lines=[]
        for c in cands:
            v=(quote_char+c.value) if quote_char else c.value
            lines.append(f"{v}\t{c.desc}" if c.desc else v)
        return "\n".join(lines)+"\n"
    if shell=='elvish':
        lines=[]
        for c in cands:
            v=(quote_char+c.value) if quote_char else c.value
            disp=c.display if c.display!="" else " "
            lines.append(f"{v}\t{1 if c.append else 0}\t{disp}\t{c.desc}\t{ELVISH_COLORS.get(c.kind,'default')}")
        return "\n".join(lines)+"\n"
    if shell=='powershell':
        lines=[]
        for c in cands:
            v=quote_if(c.value,PS_QUOTE); v=(quote_char+v) if quote_char else v
            disp=c.display if c.display!="" else " "
            lines.append(f"{v}\t{1 if c.append else 0}\t{disp}\t{c.desc}\t{c.kind}")
        return "\n".join(lines)+"\n"
    if shell=='xonsh':
        lines=[]
        for c in cands:
            v=quote_if(c.value,XON_QUOTE); v=(quote_char+v) if quote_char else v
            disp=c.display if c.display!="" else " "
            lines.append(f"{v}\t{1 if c.append else 0}\t{disp}\t{c.desc}")
        return "\n".join(lines)+"\n"
    if shell=='nushell':
        lines=[]
        for c in cands:
            v=quote_if(c.value,NU_QUOTE); v=(quote_char+v) if quote_char else v
            first=v+(' ' if c.append else '')
            lines.append(f"{first}\t{c.desc}" if c.desc else first)
        return "\n".join(lines)+"\n"
    if shell=='zsh':
        lines=[]
        for c in cands:
            v=zsh_escape_cand(c.value)+(' ' if c.append else '')
            disp_esc=c.display.replace(':','\\:')
            second=f"{disp_esc}:{c.desc}" if c.desc else disp_esc
            lines.append(f"{v}\t{second}\t{c.display}\t{c.kind}")
        return "\n".join(lines)+"\n"
    if shell=='tcsh':
        lines=[]
        for c in cands:
            v=(quote_char+c.value) if quote_char else c.value
            if len(cands)==1:
                line=tcsh_escape_cand(v)
            else:
                if c.desc:
                    line=f"{tcsh_escape_cand(v)} ({c.desc})"
                else:
                    line=tcsh_escape_cand(v)
            line=line.replace(' ','\u2800')
            lines.append(line)
        return "\n".join(lines)+"\n"
    if shell=='bash':
        # common prefix collapse for plain candidates
        if len(cands)>1 and all(not c.desc for c in cands):
            vals=[c.value for c in cands]
            # longest common prefix
            lcp=os.path.commonprefix(vals)
            if len(lcp)>len(prefix_filtered):
                return (quote_char if quote_char and prefix_filtered else "")+bash_escape_cand(lcp)+"\n"
        if len(cands)==1:
            c=cands[0]
            return (quote_char or "")+bash_escape_cand(c.value)+(' ' if c.append else '')+"\n"
        lines=[]
        all_file=all(c.is_file for c in cands)
