    except Exception:
        return []
    out=[]
    import stat as _stat
    for e in entries:
        name=e.name
        if not name.startswith(base): continue
        if not base.startswith('.') and name.startswith('.'): continue
        try:
            st=e.stat(follow_symlinks=True)
        except Exception:
